// Legacy layerStyleOwnerForTarget admits text/tilemap/free-tile, never adjustment.
void specialStyleOwnerCheck(){
 for(const std::string kind:{"text","tilemap","free-tile"}){
  Document d(2,2);
  if(kind=="text"){
   TextCelData text;text.text=u"A";timeline::Surface surface;surface.width=surface.height=2;surface.pixels={0xff123456,0,0,0};
   CHECK(d.beginTextDraft(text,surface));CHECK(d.commitTextDraft());
  }else if(kind=="tilemap"){
   CHECK(d.createTilemapLayer(1,1,U"Tiles"));d.beginStroke({0,0},0xff123456);d.commitStroke();
  }else{
   // Metadata admission only: native free-tile editing/import remains gated.
   auto state=d.timeline().state();state.layers.front().kind=kind;state.layers.front().freeTiles=free_tiles::LayerData{};state.layers.front().freeTiles->setId="style-free-set";auto freeSet=tiles::blankTileset("style-free-source",U"Source",1,1,"style-free-tile");state.layers.front().freeTiles->legacyTilesetId=freeSet.id;state.tilesets.push_back(std::move(freeSet));for(auto& c:state.cels)if(c.layerId==state.layers.front().id)c.freeTiles=free_tiles::CelData{};
   d=Document::fromImported(2,2,std::move(state),d.palette(),"style-owner",U"style-owner",std::make_shared<const std::vector<std::uint8_t>>());
  }
  const auto id=d.layer().id;CHECK(d.layer().kind==kind);
  CHECK(d.layerStyleTargets()==std::vector<std::string>{id});
  const auto* before=d.timeline().resolveSurface(d.cel().id).surface;const std::vector<Pixel> raw=before->pixels;const auto* storage=before->pixels.data();
  const auto text=d.cel().text;const auto grid=d.cel().tilemap;const auto tileset=d.layer().tilemapTilesetId;
  timeline::ColorOverlayStyle style;style.overlayEnabled=true;style.color=0xffabcdef;
  const auto history=d.historyPosition();CHECK(d.beginLayerStyle());CHECK(d.previewLayerStyle(style));CHECK(d.layerStyle(id)->color==style.color);d.cancelLayerStyle();CHECK(!d.layerStyle(id)&&d.historyPosition()==history);
  CHECK(d.beginLayerStyle());CHECK(d.commitLayerStyle(style));CHECK(d.historyPosition()==history+1);
  if(kind!="free-tile")CHECK(compositeNormalRegion(d.timeline(),d.frame().id,{0,0,2,2})[0]==style.color);
  CHECK(d.setLayerStylesEnabled(d.layerStyleTargets(),false));CHECK(!d.layerStyle(id)->enabled);d.undo();CHECK(d.layerStyle(id)->enabled);d.undo();CHECK(!d.layerStyle(id));d.redo();CHECK(d.layerStyle(id)->enabled);
  CHECK(d.layer().kind==kind&&d.layer().tilemapTilesetId==tileset);const auto* after=d.timeline().resolveSurface(d.cel().id).surface;CHECK(after->pixels==raw&&after->pixels.data()==storage);
  if(text)CHECK(d.cel().text&&d.cel().text->text==text->text&&d.cel().text->fontFamily==text->fontFamily);
  if(grid)CHECK(d.cel().tilemap&&d.cel().tilemap->cells==grid->cells);
  CHECK(d.beginLayerStyle());CHECK(d.commitLayerStyle({}));CHECK(!d.layerStyle(id));
 }
 Document seed(1,1);auto state=seed.timeline().state();state.layers.front().kind="adjustment";state.layers.front().adjustment=timeline::LayerAdjustment{};
 auto adjustment=Document::fromImported(1,1,std::move(state),seed.palette(),"adjustment-style",U"adjustment-style",std::make_shared<const std::vector<std::uint8_t>>());
 CHECK(adjustment.layerStyleTargets().empty()&&!adjustment.beginLayerStyle());CHECK(!adjustment.setLayerStylesEnabled({adjustment.layer().id},true));
}

